function catalogTermPattern(term){let p='';for(const ch of term){if(/[iIİı]/.test(ch)){p+='[iIİı]';continue}p+=('\\^$.*+?()[]{}|'.includes(ch)?'\\'+ch:ch)}return new RegExp('(^|[^\\p{L}\\p{N}])'+p+'(?=$|[^\\p{L}\\p{N}])','giu')}
function catalogText(value){let text=String(value??'');const lang=typeof currentLanguage==='undefined'?'tr':currentLanguage;if(lang==='tr'||!text)return text;const table=catalogPhrases[lang]||{},urls=[],phrases=[];text=text.replace(/https?:\/\/[^\s)\]>]+/giu,x=>{urls.push(x);return'__URL'+(urls.length-1)+'__'});for(const [source,target] of Object.entries(table))text=text.replace(catalogTermPattern(source),(_,prefix)=>{const token='__CATPHRASE'+phrases.length+'__';phrases.push(prefix+target);return token});const generic=text.match(/^(.+?) için otomatik teslimat hizmeti\.?$/iu);if(generic){const platform=generic[1],templates={en:'Automated delivery service for '+platform+'.',es:'Servicio de entrega automática para '+platform+'.',ru:'Услуга автоматической доставки для '+platform+'.',pt:'Serviço de entrega automática para '+platform+'.',de:'Automatischer Lieferservice für '+platform+'.'};text=templates[lang]||text}const rows=[...catalogTerms].sort((a,b)=>Math.max(...b.a.map(x=>x.length))-Math.max(...a.a.map(x=>x.length)));for(const row of rows){const target=row[lang];if(!target)continue;for(const source of row.a)text=text.replace(catalogTermPattern(source),(_,prefix)=>prefix+target)}text=text.replace(/__CATPHRASE(\d+)__/gu,(_,n)=>phrases[Number(n)]||_);text=text.replace(/__URL(\d+)__/gu,(_,n)=>urls[Number(n)]||_);return text}
function catalogLabel(key){const lang=typeof currentLanguage==='undefined'?'tr':currentLanguage;return(catalogUi[lang]||catalogUi.tr)[key]||key}

function translation(){return translations[currentLanguage]||translations.tr}
function applyLanguage(){const t=translation(),lang=$('#language-select');document.documentElement.lang=currentLanguage;if(lang)lang.value=currentLanguage;const title=$('#view-services .view-head h2'),desc=$('#view-services .view-head p'),search=$('#service-search'),platform=$('#platform-label'),country=$('#country-label'),sort=$('#service-sort');if(title)title.textContent=t.services;if(desc)desc.textContent=t.serviceText;if(search)search.placeholder=t.search;if(platform)platform.textContent=t.platform;if(country)country.textContent=t.country;if(!account&&$('#account-label'))$('#account-label').textContent=t.account;if(sort){sort.options[0].text=t.popular;sort.options[1].text=t.best;sort.options[2].text=t.cheap;sort.options[3].text=t.expensive;sort.options[4].text=t.fast;sort.options[5].text=t.newest}renderCatalogFilters();renderServices(search?.value||'');renderPlatformCards();renderPopular();const catSelect=$('#category-select'),serviceSelect=$('#service-select');if(catSelect){if(catSelect.options[0])catSelect.options[0].textContent=catalogLabel('chooseCategory');Array.from(catSelect.options).slice(1).forEach(option=>option.textContent=catalogText(option.value))}if(serviceSelect){if(serviceSelect.options[0]&&!serviceSelect.options[0].value)serviceSelect.options[0].textContent=selectedPlatform?catalogLabel('chooseCategoryFirst'):catalogLabel('chooseService');Array.from(serviceSelect.options).slice(1).forEach(option=>{const item=services.find(x=>String(x.id)===option.value);if(item)option.textContent=catalogText(cleanServiceName(item.name))});if(selectedService)serviceSelect.dispatchEvent(new Event('change'))}}
;(()=>{const lang=$('#language-select');if(!lang)return;applyLanguage();lang.onchange=()=>{currentLanguage=lang.value;localStorage.setItem('elturco_language',currentLanguage);applyLanguage();toast({tr:'Dil değiştirildi.',en:'Language changed.',es:'Idioma cambiado.',ru:'Язык изменён.',pt:'Idioma alterado.',de:'Sprache geändert.'}[currentLanguage])};const auth=new URLSearchParams(location.search).get('auth');if(auth){history.replaceState({},'',location.pathname+location.hash)}})();
