function applyFullLanguage(){const dict=fullTranslations[currentLanguage]||{},walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName||''))continue;const shown=node.nodeValue,stored=originalText.has(node)?originalText.get(node):shown;const lead=stored.match(/^\s*/)?.[0]||'',trail=stored.match(/\s*$/)?.[0]||'';let key=stored.trim();if(!originalText.has(node)){for(const language of Object.values(fullTranslations)){const found=Object.entries(language).find(([,value])=>value===key);if(found){key=found[0];break}}originalText.set(node,lead+key+trail)}node.nodeValue=key&&dict[key]?lead+dict[key]+trail:lead+key+trail}document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{const raw=originalPlaceholder.has(el)?originalPlaceholder.get(el):el.getAttribute('placeholder');originalPlaceholder.set(el,raw);const placeholders={en:{'Hizmet ara...':'Search services...','Adınız':'Your name','E-posta (isteğe bağlı)':'Email (optional)','Mesajınızı yazın...':'Type your message...','Kısa başlık':'Short title','Deneyimini yaz...':'Share your experience...'},es:{'Hizmet ara...':'Buscar servicios...','Kısa başlık':'Título corto','Deneyimini yaz...':'Escribe tu experiencia...'},de:{'Hizmet ara...':'Dienste suchen...','Kısa başlık':'Kurzer Titel','Deneyimini yaz...':'Erfahrung schreiben...'},pt:{'Hizmet ara...':'Buscar serviços...','Kısa başlık':'Título curto','Deneyimini yaz...':'Conte sua experiência...'},ru:{'Hizmet ara...':'Поиск услуг...','Kısa başlık':'Краткий заголовок','Deneyimini yaz...':'Опишите ваш опыт...'}};el.setAttribute('placeholder',placeholders[currentLanguage]?.[raw]||raw)})}
$('#language-select')?.addEventListener('change',()=>setTimeout(applyFullLanguage,0));setTimeout(applyFullLanguage,0);
function reviewStars(rating){return '<span class="review-stars">'+('★'.repeat(rating))+('☆'.repeat(5-rating))+'</span>'}
async function loadReviews(){const list=$('#review-list'),bars=$('#review-bars');if(!list||!bars)return;try{const reviews=await fetch('/api/reviews').then(r=>r.json());if(!Array.isArray(reviews))throw new Error();const average=reviews.length?reviews.reduce((a,x)=>a+Number(x.rating),0)/reviews.length:0;$('#review-average').textContent=reviews.length?average.toFixed(1)+' / 5':'—';$('#review-count').textContent=reviews.length+' değerlendirme';bars.innerHTML=[5,4,3,2,1].map(n=>{const count=reviews.filter(x=>x.rating===n).length,percent=reviews.length?count/reviews.length*100:0;return '<span><b>'+n+' ★</b><i><em style="width:'+percent+'%"></em></i><small>'+count+'</small></span>'}).join('');list.innerHTML=reviews.length?reviews.map(x=>'<article class="review-card panel"><div><b>'+escapeHtml(x.name)+'</b>'+reviewStars(x.rating)+'</div><h3>'+escapeHtml(x.title||'Sipariş deneyimi')+'</h3><p>'+escapeHtml(x.comment)+'</p><small>'+new Date(x.createdAt*1000).toLocaleDateString(currentLanguage)+'</small></article>').join(''):'<div class="review-empty panel">Henüz yorum yok. İlk değerlendirmeyi tamamlanmış sipariş sahibi müşterimiz bırakabilir.</div>';applyFullLanguage()}catch{list.innerHTML='<div class="review-empty panel">Yorumlar şu anda yüklenemedi.</div>'}}
function updateReviewGate(){const form=$('#review-form'),button=form?.querySelector('button[type="submit"]'),copy=form?.querySelector('p');if(!form||!button||!copy)return;form.classList.toggle('login-required',!account);button.textContent=account?'Yorumu gönder':'Giriş yap ve değerlendir';copy.textContent=account?'Değerlendirme için tamamlanmış bir siparişin bulunması gerekir.':'Değerlendirme göndermek için önce giriş yap veya ücretsiz kayıt ol.'}
$('#review-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!account){openAccount('login');toast('Değerlendirmek için giriş yap veya kayıt ol.');return}try{const r=await fetch('/api/reviews',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}),d=await r.json();if(!r.ok){toast(d.error||'Yorum gönderilemedi.');return}e.target.reset();toast('Yorumun yayınlandı.');loadReviews()}catch{toast('Bağlantı kurulamadı. Lütfen tekrar dene.')}});loadReviews();updateReviewGate();

