// Accessible, manually controllable rotating customer announcement board.
(()=>{const root=$('#ad-carousel');if(!root)return;const slides=[...root.querySelectorAll('.ad-slide')],dots=[...root.querySelectorAll('[data-ad-dot]')],current=$('#ad-current');let index=0,timer;const show=(next,reset=true)=>{index=(next+slides.length)%slides.length;slides.forEach((slide,i)=>{const active=i===index;slide.classList.toggle('active',active);slide.setAttribute('aria-hidden',String(!active))});dots.forEach((dot,i)=>{const active=i===index;dot.classList.toggle('active',active);dot.setAttribute('aria-pressed',String(active))});if(current)current.textContent=String(index+1).padStart(2,'0');if(reset)schedule()};const schedule=()=>{clearInterval(timer);if(!document.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>show(index+1,false),6500)};root.querySelector('[data-ad-prev]')?.addEventListener('click',()=>show(index-1));root.querySelector('[data-ad-next]')?.addEventListener('click',()=>show(index+1));dots.forEach((dot,i)=>dot.addEventListener('click',()=>show(i)));root.addEventListener('mouseenter',()=>clearInterval(timer));root.addEventListener('mouseleave',schedule);root.addEventListener('focusin',()=>clearInterval(timer));root.addEventListener('focusout',event=>{if(!root.contains(event.relatedTarget))schedule()});document.addEventListener('visibilitychange',schedule);schedule()})();


/* Branded, grouped order selectors. */
(()=>{const category=$('#category-select'),service=$('#service-select');if(!category||!service)return;
const labels={tr:{category:'Kategori seçin',service:'Önce kategori seçin',search:'Hizmet ara...',all:'Tüm kategoriler',more:'Daha fazla göster',less:'Daha az göster',empty:'Sonuç bulunamadı',fresh:'Yeni'},en:{category:'Choose a category',service:'Choose a category first',search:'Search services...',all:'All categories',more:'Show more',less:'Show less',empty:'No results found',fresh:'New'},es:{category:'Elige una categoría',service:'Elige primero una categoría',search:'Buscar servicios...',all:'Todas las categorías',more:'Mostrar más',less:'Mostrar menos',empty:'No se encontraron resultados',fresh:'Nuevo'},pt:{category:'Escolha uma categoria',service:'Escolha primeiro uma categoria',search:'Buscar serviços...',all:'Todas as categorias',more:'Mostrar mais',less:'Mostrar menos',empty:'Nenhum resultado',fresh:'Novo'},de:{category:'Kategorie auswählen',service:'Wähle zuerst eine Kategorie',search:'Dienste suchen...',all:'Alle Kategorien',more:'Mehr anzeigen',less:'Weniger anzeigen',empty:'Keine Ergebnisse',fresh:'Neu'},ru:{category:'Выберите категорию',service:'Сначала выберите категорию',search:'Поиск услуг...',all:'Все категории',more:'Показать ещё',less:'Свернуть',empty:'Ничего не найдено',fresh:'Новое'}};
const tr=()=>labels[currentLanguage]||labels.tr;
const mk=(select,type,title)=>{const wrap=document.createElement('div');wrap.className='order-select-wrap order-select-'+type;const trigger=document.createElement('button');trigger.type='button';trigger.className='order-select-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.innerHTML='<span class="order-select-value"></span><span class="order-select-chevron" aria-hidden="true">⌄</span>';const menu=document.createElement('div');menu.className='order-select-menu';menu.hidden=true;menu.innerHTML='<label class="order-select-search"><span aria-hidden="true">⌕</span><input type="search" autocomplete="off" placeholder="'+escapeHtml(tr().search)+'"></label><div class="order-select-options" role="listbox"></div>';select.classList.add('order-select-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');select.parentElement.insertBefore(wrap,select.nextSibling);wrap.append(trigger,menu);const value=wrap.querySelector('.order-select-value'),search=wrap.querySelector('input'),options=wrap.querySelector('.order-select-options');const close=()=>{menu.hidden=true;trigger.setAttribute('aria-expanded','false')};const open=()=>{menu.hidden=false;trigger.setAttribute('aria-expanded','true');search.value='';search.placeholder=tr().search;draw();requestAnimationFrame(()=>search.focus())};trigger.addEventListener('click',()=>menu.hidden?open():close());search.addEventListener('input',draw);document.addEventListener('pointerdown',e=>{if(!wrap.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){close();trigger.focus()}});let api;select.addEventListener('change',()=>{api.drawValue();if(type==='category')populateServices();else draw()});api={wrap,trigger,menu,value,search,options,close,open,draw:()=>{search.placeholder=tr().search;draw()},drawValue:()=>{let text=select.value?catalogText(cleanServiceName(select.value)):type==='service'?(category.value||selectedPlatform?catalogLabel('chooseService'):catalogLabel('chooseCategoryFirst')):catalogLabel('chooseCategory');if(type==='service'&&select.value){const s=services.find(x=>String(x.id)===select.value);if(s)text=catalogText(cleanServiceName(s.name))}value.innerHTML=(select.value?platformLogo(type==='category'?select.value.split(' · ')[0]:services.find(x=>String(x.id)===select.value)?.platform):'')+'<span>'+escapeHtml(text)+'</span>'}};return api;function draw(){if(type==='category')drawCategories(options,search.value);else drawServices(options,search.value)}};
const cat=mk(category,'category',tr().category),svc=mk(service,'service',tr().service);
function drawCategories(host,query){const q=query.trim().toLocaleLowerCase(currentLanguage==='tr'?'tr':currentLanguage),rows=[...category.options].slice(1).filter(o=>!q||catalogText(o.value).toLocaleLowerCase(currentLanguage==='tr'?'tr':currentLanguage).includes(q));const groups=new Map();rows.forEach(o=>{const [platform,...rest]=o.value.split(' · ');if(!groups.has(platform))groups.set(platform,[]);groups.get(platform).push({value:o.value,label:rest.join(' · '),selected:o.selected})});const ordered=[...groups.keys()].sort((x,y)=>x.localeCompare(y,currentLanguage));host.innerHTML=rows.length?ordered.map(platform=>'<div class="order-option-group"><div class="order-option-heading">'+platformLogo(platform)+'<b>'+escapeHtml(catalogText(platform))+'</b><span>'+groups.get(platform).length+'</span></div>'+groups.get(platform).sort((x,y)=>x.label.localeCompare(y.label,currentLanguage)).map(item=>'<button type="button" class="order-option '+(item.selected?'selected':'')+'" role="option" aria-selected="'+item.selected+'" data-value="'+escapeHtml(item.value)+'">'+platformLogo(platform)+'<span>'+escapeHtml(catalogText(cleanServiceName(item.label)))+'</span></button>').join('')+'</div>').join(''):'<div class="order-select-empty">'+tr().empty+'</div>';host.querySelectorAll('[data-value]').forEach(button=>button.addEventListener('click',()=>{category.value=button.dataset.value;category.dispatchEvent(new Event('change',{bubbles:true}));cat.close()}))}
function populateServices(){const value=category.value,matching=value?services.filter(s=>s.platform+' · '+s.category===value):selectedPlatform?services.filter(s=>cleanServiceName(s.platform)===cleanServiceName(selectedPlatform)||(selectedPlatform==='Twitter'&&cleanServiceName(s.platform)==='X / Twitter')):[];service.innerHTML='<option value="">'+(value||selectedPlatform?catalogLabel('chooseService'):catalogLabel('chooseCategoryFirst'))+'</option>'+matching.map(s=>'<option value="'+s.id+'">'+escapeHtml(catalogText(s.name))+'</option>').join('');service.value='';selectedService=null;$('#service-id').value='';updatePrice();svc.drawValue();svc.draw();setOrderStep(value?3:2)}
function drawServices(host,query){const q=query.trim().toLocaleLowerCase(currentLanguage==='tr'?'tr':currentLanguage),rows=[...service.options].slice(1).map(o=>services.find(s=>String(s.id)===o.value)).filter(Boolean).filter(s=>!q||(s.name+' '+s.id+' '+s.platform+' '+s.category+' '+catalogText(s.name)).toLocaleLowerCase(currentLanguage==='tr'?'tr':currentLanguage).includes(q));if(!rows.length){host.innerHTML='<div class="order-select-empty">'+tr().empty+'</div>';return}const groups=new Map();rows.forEach(s=>{const key=s.platform+' · '+s.category;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s)});host.innerHTML=[...groups.keys()].sort((x,y)=>x.localeCompare(y,currentLanguage)).map(key=>{const items=groups.get(key).sort((x,y)=>catalogText(cleanServiceName(x.name)).localeCompare(catalogText(cleanServiceName(y.name)),currentLanguage));return '<div class="order-option-group"><div class="order-option-heading">'+platformLogo(items[0].platform)+'<b>'+escapeHtml(catalogText(cleanServiceName(key)))+'</b><span>'+items.length+'</span></div>'+items.map(s=>'<button type="button" role="option" aria-selected="'+(String(s.id)===service.value)+'" class="order-option order-service-option '+(String(s.id)===service.value?'selected':'')+'" data-service-id="'+s.id+'">'+platformLogo(s.platform)+'<small class="order-service-id">'+s.id+'</small><span>'+escapeHtml(catalogText(cleanServiceName(s.name)))+'</span>'+(s.isNew===true||s.isNew===1||s.isNew==='1'?'<em class="order-new-badge">'+tr().fresh+'</em>':'')+'<strong>'+money(s.salePrice/100)+' / 1.000</strong></button>').join('')+'</div>'}).join('');host.querySelectorAll('[data-service-id]').forEach(button=>button.addEventListener('click',()=>{const chosen=services.find(s=>String(s.id)===button.dataset.serviceId);if(chosen){const categoryValue=chosen.platform+' · '+chosen.category;if(category.value!==categoryValue){category.value=categoryValue;category.dispatchEvent(new Event('change',{bubbles:true}))}}service.value=button.dataset.serviceId;service.dispatchEvent(new Event('change',{bubbles:true}));svc.close()}))}
category.addEventListener('change',()=>{cat.drawValue();cat.draw()});service.addEventListener('change',()=>svc.drawValue());$('#language-select')?.addEventListener('change',()=>{cat.drawValue();svc.drawValue();cat.draw();svc.draw()});cat.drawValue();svc.drawValue();})();


