(()=>{const pickers=[...document.querySelectorAll('[data-platform-pick]')],category=document.querySelector('#category-select'),service=document.querySelector('#service-select');function update(){const selected=services.find(x=>x.id===Number(service?.value));const amount=document.querySelector('#amount')?.textContent||'₺0,00';const total=document.querySelector('#summary-total');if(total)total.textContent=amount;const name=document.querySelector('#summary-service');if(name)name.textContent=selected?.name||'Henüz seçilmedi';const limits=document.querySelector('#summary-limits');if(limits)limits.textContent=selected?Number(selected.minOrder).toLocaleString('tr-TR')+' / '+Number(selected.maxOrder).toLocaleString('tr-TR'):'—';const start=document.querySelector('#summary-start');if(start)start.textContent=selected?etaFor(selected):'Hizmeti seç';const refill=document.querySelector('#summary-refill');if(refill)refill.textContent=selected?(/refill/i.test(selected.description||'')?'Bilgi hizmet detayında':'Detayda belirtilir'):'Hizmeti seç';const qty=document.querySelector('#quantity')?.value;const steps=[...document.querySelectorAll('.order-steps .step')];const stage=document.querySelector('#quantity')?.value?4:selected?3:category?.value?2:1;steps.forEach((step,i)=>{step.classList.toggle('active',i===stage-1);step.classList.toggle('done',i<stage-1)});const form=document.querySelector('#order-form');if(form)form.classList.toggle('has-quantity',Boolean(qty));}
pickers.forEach(button=>button.addEventListener('click',()=>chooseOrderPlatform(button.dataset.platformPick)));
document.querySelector('#category-select')?.addEventListener('change',()=>{const platform=category.value.split(' · ')[0],buttonPlatform=category.value?(platform==='X / Twitter'?'Twitter':platform):selectedPlatform;pickers.forEach(x=>{const active=x.dataset.platformPick===buttonPlatform;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});setTimeout(update,0)});service?.addEventListener('change',()=>setTimeout(update,0));document.querySelector('#quantity')?.addEventListener('input',update);document.querySelector('#quantity')?.addEventListener('change',update);document.querySelector('#amount')&&new MutationObserver(update).observe(document.querySelector('#amount'),{childList:true,subtree:true,characterData:true});
document.querySelector('#global-service-search')?.addEventListener('input',event=>{const q=event.target.value.trim();if(q&&!document.querySelector('#view-services')?.classList.contains('active'))showView('services');const search=document.querySelector('#service-search');if(search){search.value=q;search.dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.querySelector('#global-service-search')?.focus()}});
document.querySelectorAll('.summary-submit').forEach(button=>button.addEventListener('click',()=>document.querySelector('#order-form')?.requestSubmit()));update();})();

document.querySelectorAll('.nav-item[data-order-focus]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(item=>item.classList.remove('active'));button.classList.add('active')}));

(()=>{const title=document.querySelector('.welcome h2');if(!title)return;const desired='Bugün neyi büyütüyoruz?';const apply=()=>{if(title.textContent.trim()!==desired)title.innerHTML='Bugün neyi <em>büyütüyoruz?</em>'};apply();new MutationObserver(apply).observe(title,{childList:true,subtree:true,characterData:true})})();

